python
def positiveTraysPositiveProofStrip(readings, k):
    a=readings
    out=[]
    for x in a:
        if x>0: out.append(x)
    return [x for x in out if x>0]


java
class Solution {
  public int[] positiveTraysPositiveProofStrip(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {for(int x:a)if(x>0)out.add(x);}
    return out.stream().filter(x->x>0).mapToInt(Integer::intValue).toArray();
  }
}
